import{_ as p,o as e,c as t,ac as a}from"./chunks/framework.B-3EzaJq.js";const m=JSON.parse('{"title":"中国共产党第十二届中央委员会第三次全体会议关于召开党的全国代表会议的决定","description":"","frontmatter":{"prev":{"text":"中共中央关于经济体制改革的决定","link":"./中共中央关于经济体制改革的决定"},"next":{"text":"陈云在党的十二届三中全会上的书面发言","link":"./陈云在党的十二届三中全会上的书面发言"}},"headers":[],"relativePath":"12/3/中国共产党第十二届中央委员会第三次全体会议关于召开党的全国代表会议的决定.md","filePath":"12/3/中国共产党第十二届中央委员会第三次全体会议关于召开党的全国代表会议的决定.md"}'),o={name:"12/3/中国共产党第十二届中央委员会第三次全体会议关于召开党的全国代表会议的决定.md"};function r(n,_,s,c,i,l){return e(),t("div",null,[..._[0]||(_[0]=[a('<h1 id="中国共产党第十二届中央委员会第三次全体会议关于召开党的全国代表会议的决定" tabindex="-1">中国共产党第十二届中央委员会第三次全体会议关于召开党的全国代表会议的决定 <a class="header-anchor" href="#中国共产党第十二届中央委员会第三次全体会议关于召开党的全国代表会议的决定" aria-label="Permalink to &quot;中国共产党第十二届中央委员会第三次全体会议关于召开党的全国代表会议的决定&quot;">​</a></h1><p><em>（中国共产党第十二届中央委员会第三次全体会议一九八四年十月二十日通过）</em></p><p>  一、根据党章第十二条的规定，决定于一九八五年九月召开党的全国代表会议。</p><p>  二、党的全国代表会议的议题是：</p><p>  1、讨论通过关于国民经济和社会发展第七个五年计划纲要的建议；</p><p>  2、增选中央委员会成员等组织事项。</p><p>  三、参加党的全国代表会议的代表共一千人左右：</p><p>  1、中央委员会委员和候补委员；</p><p>  2、中央顾问委员会委员；</p><p>  3、中央纪律检查委员会委员；</p><p>  4、不是中央三个委员会成员的省、自治区、直辖市、大军区、中央党政军各部门和群众团体的主要负责人；</p><p>  5、十二大以来在经济、政法、外交、军事、科学、技术、文化、教育、卫生、体育等各条战线作出重大贡献的党员，特别是中青年党员。名额由中央分配给省、自治区、直辖市党委和中央直属机关党委、中央国家机关党委、解放军总政治部，并由他们召开党委或党组扩大会议推选，报中央审批。</p><p>  出席党的全国代表会议的代表都有表决权、选举权。</p><p>  四、全会号召全党、全军、全国各族人民为全面超额完成第六个五年计划，迎接党的全国代表会议的胜利召开而奋斗！</p><blockquote><p>  附：中国共产党章程第十二条</p><p>  第十二条 党的县级和县级以上委员会在必要时可以召集代表会议，讨论和决定需要及时解决的重大问题。代表会议代表的名额和产生办法，由召集代表会议的委员会决定。</p></blockquote>',15)])])}const f=p(o,[["render",r]]);export{m as __pageData,f as default};
